pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(bytes32 fuzzHash, uint64 number, uint64 timestamp) public {
        vm.prank(address(0));
        c.setL1BlockValues(number, timestamp, 0, fuzzHash, 0, bytes32(0), 0, 0);
        assertTrue(c.hash() == bytes32(0));
    }
}
